// Generates the per-language pages from templates/ and locales.mjs:
//   /index.html                 picks a language (saved choice, then the browser's languages) and redirects
//   /{lang}/index.html          the home page
//   /{lang}/{privacy,terms,licenses}.html
// Runs before `vite` and `vite build` (see package.json). The generated files are not edited by hand.
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { DEFAULT_LANG, LANGS, LOCALES } from '../locales.mjs'

const root = resolve(import.meta.dirname, '..')

// The legal texts live in the app (../legal). Keep a copy inside site/legal so the site
// also builds when only this folder is deployed (Vercel with "site" as the root).
const LEGAL_FILES = ['privacidade.md', 'termos.md', 'privacy.en.md', 'terms.en.md', 'privacy.es.md', 'terms.es.md', 'licenses.json']
const appLegal = resolve(root, '..', 'legal')
if (existsSync(appLegal)) {
  mkdirSync(join(root, 'legal'), { recursive: true })
  for (const f of LEGAL_FILES) copyFileSync(join(appLegal, f), join(root, 'legal', f))
}
const home = readFileSync(join(root, 'templates', 'home.html'), 'utf8')

/** Canonical address once the site is online (used for hreflang links). */
const ORIGIN = 'https://halyardbrowser.com'

// The root redirect lives in its own file: the site's CSP forbids inline scripts.
// Saved choice first, then the browser's own languages (pt-BR, pt-PT -> pt; es-ES, es-MX -> es), else English.
writeFileSync(
  join(root, 'public', 'lang.js'),
  `// generated by scripts/pages.mjs
;(function () {
  var langs = ${JSON.stringify(LANGS)}
  var pick = null
  try { pick = localStorage.getItem('halyard-lang') } catch (e) {}
  if (langs.indexOf(pick) < 0) {
    pick = null
    var wanted = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || '']
    for (var i = 0; i < wanted.length && !pick; i++) {
      var base = String(wanted[i]).toLowerCase().split('-')[0]
      if (langs.indexOf(base) >= 0) pick = base
    }
  }
  location.replace('/' + (pick || '${DEFAULT_LANG}') + '/' + location.hash)
})()
`
)

const fill = (tpl, dict) =>
  tpl.replace(/\{\{(\w+)\}\}/g, (_, key) => {
    if (!(key in dict)) throw new Error(`missing text "${key}"`)
    return dict[key]
  })

const alternates = (page) =>
  [
    ...LANGS.map((l) => `<link rel="alternate" hreflang="${LOCALES[l].htmlLang}" href="${ORIGIN}/${l}/${page}" />`),
    `<link rel="alternate" hreflang="x-default" href="${ORIGIN}/${page === '' ? '' : `${DEFAULT_LANG}/${page}`}" />`
  ].join('\n    ')

/** EN · PT · ES switch; the choice is remembered by the root page. */
const langSwitch = (lang, page) =>
  `<nav class="lang-switch mono" aria-label="${LOCALES[lang].langLabel}">${LANGS.map(
    (l) =>
      `<a href="/${l}/${page}" hreflang="${LOCALES[l].htmlLang}" lang="${LOCALES[l].htmlLang}" data-lang="${l}" title="${LOCALES[l].langName}"${l === lang ? ' aria-current="true"' : ''}>${l}</a>`
  ).join('')}</nav>`

const legal = (lang, doc) => {
  const t = LOCALES[lang]
  return `<!doctype html>
<html lang="${t.htmlLang}">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${t[`${doc}Title`]} — Halyard</title>
    <meta name="theme-color" content="#f0ece3" />
    <link rel="icon" href="/icon.png" />
    ${alternates(`${doc}.html`)}
  </head>
  <body class="legal" data-doc="${doc}" data-lang="${lang}">
    <header class="legal-nav">
      <a class="brand" href="/${lang}/" aria-label="${t.back}"><img src="/icon.png" alt="" width="28" height="28" /><span>Halyard</span></a>
      <nav aria-label="${t.docsLabel}">
        <a href="/${lang}/privacy.html"${doc === 'privacy' ? ' aria-current="page"' : ''}>${t.privacy}</a>
        <a href="/${lang}/terms.html"${doc === 'terms' ? ' aria-current="page"' : ''}>${t.terms}</a>
        <a href="/${lang}/licenses.html"${doc === 'licenses' ? ' aria-current="page"' : ''}>${t.licenses}</a>
      </nav>
      ${langSwitch(lang, `${doc}.html`)}
    </header>
    <main class="legal-main" id="doc"></main>
    <script type="module" src="/src/legal.js"></script>
  </body>
</html>
`
}

const chooser = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Halyard Browser</title>
    <meta name="theme-color" content="#05070f" />
    <link rel="icon" href="/icon.png" />
    ${alternates('')}
    <script src="/lang.js"></script>
    <style>
      body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: #05070f; color: #eef0ff; font: 16px system-ui, sans-serif; }
      a { color: inherit; margin: 0 10px; }
    </style>
  </head>
  <body>
    <noscript>
      ${LANGS.map((l) => `<a href="/${l}/" hreflang="${LOCALES[l].htmlLang}">${LOCALES[l].langName}</a>`).join('\n      ')}
    </noscript>
  </body>
</html>
`

writeFileSync(join(root, 'index.html'), chooser)
for (const lang of LANGS) {
  const dir = join(root, lang)
  mkdirSync(dir, { recursive: true })
  const dict = { ...LOCALES[lang], lang, alternates: alternates(''), langSwitch: langSwitch(lang, '') }
  writeFileSync(join(dir, 'index.html'), fill(home, dict))
  for (const doc of ['privacy', 'terms', 'licenses']) writeFileSync(join(dir, `${doc}.html`), legal(lang, doc))
}
console.log(`pages: ${LANGS.join(', ')} (${LANGS.length * 4 + 1} files)`)
